/* Offline, dependency-free PDF download for the Departmental Linkage Plan. */
(function(){'use strict';
 const W=842,H=595,M=36, D=[17,46,80], T=[16,138,123];
 const BRAND_JPEG='';
 const safe=v=>String(v==null?'':v).replace(/&amp;/g,'&').replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/[\u2013\u2014]/g,'-').replace(/\u2026/g,'...').replace(/\u00a0/g,' ').replace(/[^\x20-\x7e]/g,' ').replace(/\s+/g,' ').trim()||'-';
 const esc=s=>safe(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
 const color=c=>c.map(n=>(n/255).toFixed(3)).join(' ');
 const approx=(s,size)=>safe(s).length*size*.49;
 function wrap(v,width,size){let out=[],line='';for(const word of safe(v).split(' ')){
  if(approx(word,size)>width){if(line){out.push(line);line=''}let cut='';for(const ch of word){if(approx(cut+ch,size)>width && cut){out.push(cut);cut=''}cut+=ch}line=cut;continue}
  if(line&&approx(line+' '+word,size)>width){out.push(line);line=word}else line+=(line?' ':'')+word;
 }if(line)out.push(line);return out.length?out:['-'];}
 function makeDoc(){let pages=[],p=[];const line=(x1,y1,x2,y2,c=[210,223,233])=>p.push(`${color(c)} RG 0.6 w ${x1} ${H-y1} m ${x2} ${H-y2} l S`);
 const fill=(x,y,w,h,c)=>p.push(`${color(c)} rg ${x} ${H-y-h} ${w} ${h} re f`);
 const txt=(v,x,y,size=9,bold=false,c=[30,47,68])=>p.push(`BT /${bold?'F2':'F1'} ${size} Tf ${color(c)} rg 1 0 0 1 ${x} ${H-y} Tm (${esc(v)}) Tj ET`);
 const page=(title,sub,cover=false)=>{if(p.length)pages.push(p);p=[];if(cover){fill(0,0,W,H,[247,250,252]);fill(0,0,W,154,D);fill(M,27,149,91,[255,255,255]);p.push(`q 143 0 0 88 ${M+3} ${H-116} cm /Im1 Do Q`);txt('OFFICE OF EXTERNAL LINKAGES / ANALYTICS',217,53,10,true,[181,218,222]);txt('DEPARTMENTAL EXTERNAL LINKAGE',217,83,20,true,[255,255,255]);txt('PLAN PERFORMANCE REPORT',217,111,19,true,[255,255,255]);txt('TENTATIVE  |  FILTERED PLANNING INTELLIGENCE',217,133,9,false,[206,233,238]);fill(0,154,W,6,T);}else{fill(0,0,W,82,D);fill(M,12,112,48,[255,255,255]);p.push(`q 108 0 0 46 ${M+2} ${H-59} cm /Im1 Do Q`);txt('INSTITUTIONAL ENGAGEMENT',164,28,15,true,[255,255,255]);txt(title,164,49,11,true,[255,255,255]);txt(sub,164,65,8,false,[224,242,247]);fill(0,80,W,3,T);}};
 const finish=()=>{if(p.length)pages.push(p);let count=pages.length;
  pages.forEach((commands,i)=>{p=commands;line(M,558,W-M,558);txt('THE UNIVERSITY OF LAHORE  |  OFFICE OF EXTERNAL LINKAGES',M,572,8);txt(`Page ${i+1} of ${count}`,W-M-62,572,8);});
  let imageData=atob(BRAND_JPEG);let objects=[null,'<< /Type /Catalog /Pages 2 0 R >>',null,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>',`<< /Type /XObject /Subtype /Image /Width 793 /Height 336 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imageData.length} >>\nstream\n${imageData}\nendstream`];
  let kids=[];for(let i=0;i<count;i++){let pageId=objects.length,contentId=pageId+1;kids.push(`${pageId} 0 R`);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> /XObject << /Im1 5 0 R >> >> /Contents ${contentId} 0 R >>`);let stream=pages[i].join('\n')+'\n';objects.push(`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);}
  objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${count} >>`;
  let result='%PDF-1.4\n%UOL\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=result.length;result+=`${i} 0 obj\n${objects[i]}\nendobj\n`;}let xref=result.length;result+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;for(let i=1;i<objects.length;i++)result+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;result+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;return new Blob([Uint8Array.from(result, ch=>ch.charCodeAt(0))],{type:'application/pdf'});
 };
 return {page,txt,fill,line,wrap,finish};}
 function table(doc,columns,rows,widths,startY,opts={}){let y=startY,fs=opts.fontSize||8,lh=fs+3,pad=opts.compact?3:5,headH=opts.compact?20:23;
 const header=()=>{doc.fill(M,y,W-2*M,headH,D);let x=M;columns.forEach((h,i)=>{doc.txt(h,x+pad,y+15,8,true,[255,255,255]);x+=widths[i]});y+=headH;};
 header();for(const row of rows){let cells=row.map((v,i)=>doc.wrap(v,widths[i]-2*pad,fs));let maxLines=Math.max(...cells.map(x=>x.length));let rowH=maxLines*lh+2*pad;
 if(rowH>430){ // Split unusually long content into additional physical table rows.
  let per=Math.max(1,Math.floor((430-2*pad)/lh));for(let at=0;at<maxLines;at+=per){const portion=cells.map(c=>c.slice(at,at+per).join(' ')); y=draw(portion.map((v,i)=>doc.wrap(v,widths[i]-2*pad,fs)));}continue;
 }
 y=draw(cells);
 }
 function draw(cells){const height=Math.max(...cells.map(x=>x.length))*lh+2*pad;if(y+height>548){doc.page(opts.title||'SECTION 2 | ACTIVITY DETAILS',opts.subtitle||'Continued report');y=91;header();}doc.fill(M,y,W-2*M,height,opts.alt&&Math.round(y)%2?[247,250,252]:[251,252,254]);let x=M;cells.forEach((c,i)=>{c.forEach((s,j)=>doc.txt(s,x+pad,y+pad+fs+j*lh,fs));x+=widths[i]});doc.line(M,y+height,W-M,y+height);return y+height;}
 return y;
 }
 function groupCounts(data,key){const result=new Map();for(const row of data){const name=safe(row[key]);if(name==='-'||!name)continue;result.set(name,(result.get(name)||0)+1);}return [...result].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));}
 function barChart(doc,title,subtitle,entries,startY,maxRows=12){
  doc.txt(title,M,startY,13,true,D);doc.txt(subtitle,M,startY+17,8,false,[90,111,130]);
  if(!entries.length){doc.txt('No matching plans for this selection.',M,startY+48,10);return;}
  const visible=entries.slice(0,maxRows),max=Math.max(1,...visible.map(x=>x[1]));
  const labelW=235,chartX=M+labelW+8,chartW=390,rowH=Math.min(30,Math.max(22,345/Math.max(1,visible.length)));let y=startY+33;
  visible.forEach(([name,value],index)=>{
   if(index%2===0)doc.fill(M,y-9,W-M*2,rowH,[246,249,251]);
   let lines=doc.wrap(name,labelW-12,8);if(lines.length>2)lines=[lines[0],lines[1].slice(0,46)+'...'];
   lines.forEach((line,j)=>doc.txt(line,M+4,y+1+j*9,8));
   doc.fill(chartX,y-5,chartW,10,[229,236,241]);
   doc.fill(chartX,y-5,chartW*value/max,10,index%2?T:[36,105,158]);
   doc.txt(String(value),chartX+chartW+12,y+4,9,true,D);
   y+=rowH;
  });
  if(entries.length>maxRows)doc.txt(`${entries.length-maxRows} further categories are included in the detailed data.`,M,y+14,8);
 }
 function summaryTable(doc,title,sub,entries){
  doc.page(title.toUpperCase(),'UNIVERSITY OF LAHORE / OFFICE OF EXTERNAL LINKAGES');
  doc.txt(sub,M,108,11,true,D);
  const total=entries.reduce((n,e)=>n+e[1],0);
  const rows=entries.map(([name,n])=>[name,String(n),total?`${(n/total*100).toFixed(1)}%`:'0.0%']);
  table(doc,['CATEGORY / GROUP','CLEANED PLANS','SHARE'],rows.length?rows:[['No matching data','0','0%']],[500,145,125],126,{fontSize:9,title:title.toUpperCase(),subtitle:sub});
 }
 function chartPages(doc,data){
  const charts=[
   ['FACULTY-WISE ACTIVITY PLANS','Activity plans reported by faculty','Faculty',14],
   ['ACTIVITY TYPE DISTRIBUTION','Distinct cleaned plans by standardized category','Standardized Activity Type',14],
   ['DEPARTMENT-WISE ACTIVITY PLANS','Activity plans reported by department','Department',14],
   ['PARTNER / INSTITUTION OVERVIEW','Leading external partners named in plans','Target Partner / Institution',14],
  ];
  let i=0;
  for(const [title,subtitle,key,limit] of charts){doc.page('GRAPHICAL SUMMARY',`GRAPH ${++i} OF ${charts.length}  |  ${title}`);const entries=groupCounts(data,key);barChart(doc,title,subtitle,entries,110,limit);doc.txt(`Graph ${i} of ${charts.length}  |  Filtered total: ${data.length} distinct cleaned plans`,M,527,9,false,[90,111,130]);}
 }
 function card(doc,x,y,w,title,value,caption,color){doc.fill(x,y,w,103,[250,252,254]);doc.fill(x,y,w,5,color);doc.txt(title.toUpperCase(),x+12,y+26,9,true,[74,98,119]);doc.txt(String(value),x+12,y+67,25,true,D);doc.txt(caption,x+12,y+88,8,false,[111,132,151]);}
 function generate(data,selection,submissionCount,facultyCount=null,departmentCount=null){
  const doc=makeDoc(),facultyTotal=facultyCount??new Set(data.map(r=>r.Faculty).filter(v=>safe(v)!=='-')).size;
  const deptTotal=departmentCount??new Set(data.map(r=>r.Department).filter(v=>safe(v)!=='-')).size;
  const groups=groupCounts(data,'Standardized Activity Type');
  // Branded cover, modelled on the provided OEL sample. No organization box on the cover.
  doc.page('PLAN PERFORMANCE REPORT','OFFICE OF EXTERNAL LINKAGES',true);
  doc.txt('REPORT SCOPE',M,205,13,true,D);doc.line(M,217,W-M,217,[207,221,230]);
  const selected=Object.fromEntries(selection.map(([k,v])=>[String(k).toLowerCase(),v]));
  const scopes=[['SEMESTER',selected.session||selected.semester||'All Semesters'],['FACULTY',selected.faculty||'All Faculties'],['DEPARTMENT',selected.department||'All Departments'],['ACTIVITY TYPE',selected['activity type']||'All Activity Types']];
  const bw=185,by=232;
  scopes.forEach(([label,value],i)=>{const x=M+i*197;doc.fill(x,by,bw,85,[255,255,255]);doc.fill(x,by,bw,3,T);doc.txt(label,x+10,by+20,9,true,T);doc.wrap(value,bw-20,9).slice(0,4).forEach((line,j)=>doc.txt(line,x+10,by+44+j*12,9,false,D));});
  doc.fill(M,360,370,78,[255,255,255]);doc.fill(M,360,5,78,T);doc.txt('DEAN OSA',M+18,386,9,true,[77,105,121]);doc.txt('Ms. Ammara Awais Raoof',M+18,416,12,true,D);
  doc.fill(436,360,370,78,[255,255,255]);doc.fill(436,360,5,78,[42,107,169]);doc.txt('DIRECTOR OEL',454,386,9,true,[77,105,121]);doc.txt('Dr. Muhammad Shafique',454,416,12,true,D);
  doc.txt('Generated: '+new Date().toLocaleString('en-GB'),M,488,9,false,[85,110,130]);
  doc.txt('15-submission plan source; duplicate and null activity entries excluded.',M,508,9,false,[85,110,130]);
  // KPI summary, full source roster counts, not only submissions with cleaned plans.
  doc.page('ACTIVITY REPORT','UNIVERSITY OF LAHORE / OFFICE OF EXTERNAL LINKAGES');
  doc.txt('Departmental External Linkage Plan - Section 2',M,108,14,true,D);
  const x=[M,M+197,M+394,M+591];
  card(doc,x[0],137,179,'Cleaned Activity Plans',data.length,'Distinct retained activity rows',T);
  card(doc,x[1],137,179,'Original Submissions',submissionCount,'Submission roster in scope',[42,107,169]);
  card(doc,x[2],137,179,'Faculties',facultyTotal,'Full reporting roster',[109,83,183]);
  card(doc,x[3],137,179,'Departments',deptTotal,'Full reporting roster',[19,135,159]);
  card(doc,x[0],257,179,'Activity Categories',groups.length,'Named categories',T);
  card(doc,x[1],257,179,'Named Partners',groupCounts(data,'Target Partner / Institution').length,'In filtered activity plans',[42,107,169]);
  doc.txt('REPORTING NOTE',M,411,10,true,T);
  doc.wrap('Figures count cleaned planned activity records, not completed events or participants. Descriptive How Many values remain as originally entered.',W-2*M,10).forEach((l,i)=>doc.txt(l,M,432+i*15,10));
  summaryTable(doc,'Faculty-wise Activities','Faculty summary with activity-plan counts',groupCounts(data,'Faculty'));
  summaryTable(doc,'Activity Breakdown','Standardized activity categories',groups);
  summaryTable(doc,'Department-wise Activities','Department summary with activity-plan counts',groupCounts(data,'Department'));
  summaryTable(doc,'Organization-wise Activities','Partner / institution summary',groupCounts(data,'Target Partner / Institution'));
  doc.page('EXPECTED OUTCOMES','PLANNED ENGAGEMENT OUTCOMES');
  doc.txt('Expected Outcomes Recorded in the Source',M,111,13,true,D);
  let outcomes=[...new Set(data.map(r=>safe(r['Expected Outcome'])).filter(v=>v!=='-'))];let oy=138;
  for(const out of outcomes.slice(0,13)){let lines=doc.wrap(out,W-M*2-18,8);if(oy+lines.length*11+11>534){doc.page('EXPECTED OUTCOMES','CONTINUED');oy=106;}doc.fill(M,oy-9,4,Math.max(15,lines.length*11),T);lines.forEach((l,i)=>doc.txt(l,M+13,oy+i*11,8));oy+=lines.length*11+11;}
  doc.page('REMARKS','SOURCE DATA AND INTERPRETATION');
  doc.txt('Management Review Notes',M,110,13,true,D);
  const remarks=['This is a departmental planning dataset and is separate from the earlier UOL progress report.','15 submissions remain in the roster, including submissions with no retained valid Section 2 activity.','The cleaned activity table retains 107 distinct plans after excluding 9 duplicate activities and 2 null placeholders.','Planned quantities and descriptive participant ranges must not be represented as completed activities or total participants.','Semester classifications follow the source Session and Year fields. Tentative dates remain in the Excel source and do not determine semester reporting.'];let ry=142;
  for(const r of remarks){let ls=doc.wrap(r,W-M*2-17,10);doc.fill(M,ry-9,4,Math.max(16,ls.length*14),T);ls.forEach((l,i)=>doc.txt(l,M+14,ry+i*14,10));ry+=ls.length*14+20;}
  chartPages(doc,data);
  doc.page('DETAILED RECORDS',`${data.length} FILTERED SECTION 2 PLANS`);
  doc.txt('One row per retained plan. Semester is taken from the original Session and Year fields.',M,102,9);
  const widths=[67,118,104,174,158,88,61];const heads=['Ref #','Faculty / Dept','Activity type','Description','Partner / Institution','Semester','How Many'];
  const rows=data.map(r=>[r['Submission Ref'],[r.Faculty,r.Department].filter(Boolean).join(' / '),r['Standardized Activity Type'],r['Brief Description'],r['Target Partner / Institution'],[r.Session,r.Year].filter(Boolean).join(' ')||'Not specified',r['How Many (original)']]);
  table(doc,heads,rows.length?rows:[['-','-','No matching plans','-','-','-','-']],widths,116,{fontSize:7,title:'DETAILED RECORDS',subtitle:`${data.length} filtered activity plans`});
  return doc.finish();
 }
 window.UOLPDF={generate,download(data,filters,count){const blob=generate(data,filters,count),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='UOL_Departmental_External_Linkage_Plan_Semester_Wise_Report.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}};
})();
